import{_ as i,o as t,c as a,ad as l}from"./chunks/framework.BJi0JF_z.js";const u=JSON.parse('{"title":"عیب‌یابی شبکه‌ موبایل","description":"عیب‌یابی اتصال به شبکه‌ در سیستم‌عامل اندروید گوشی‌های سامسونگ","frontmatter":{"layout":"doc","outline":"deep","lang":"fa-IR","dir":"rtl","title":"عیب‌یابی شبکه‌ موبایل","description":"عیب‌یابی اتصال به شبکه‌ در سیستم‌عامل اندروید گوشی‌های سامسونگ","date":"2026-11-17T00:00:00.000Z","category":"ابزارها و سرور","icon":"⚙️","editLink":true,"head":[["meta",{"name":"description","content":"عیب‌یابی, شبکه, سامسونگ, نتوورک, دیتای موبایل, اینترنت سیمکارت, وای‌فای, مودم, apn, نام نقاط دستیابی, دی‌ان‌اس, سامسونگ, private dns, Android Network Diagnostic"}],["meta",{"name":"keywords","content":"Android Network Diagnostic, apn, cellular, wifi, network, Debug, private dns, routing rules, iran, irancell, hamrah aval, mci, mtn, mkb, Samsung, A series"}]]},"headers":[],"relativePath":"topics/network-diagnostic.md","filePath":"topics/network-diagnostic.md"}'),o={name:"topics/network-diagnostic.md"};function r(n,e,s,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="android-network-diagnostic" tabindex="-1">Android Network Diagnostic <a class="header-anchor" href="#android-network-diagnostic" aria-label="Permalink to &quot;Android Network Diagnostic&quot;">​</a></h1><p>راهنمای بررسی تنظیمات شبکه و عیب‌یابی اتصال VPN در گوشی‌های Samsung Galaxy و سایر دستگاه‌های Android.</p><blockquote><p>هدف این راهنما شناسایی اختلالات احتمالی در تنظیمات شبکه، DNS، سیستم‌عامل و کلاینت‌های VPN است. قبل از انجام هرگونه تغییر، وضعیت فعلی تنظیمات را ثبت کنید.</p></blockquote><h2 id="_1-اطلاعات-دستگاه" tabindex="-1">1. اطلاعات دستگاه <a class="header-anchor" href="#_1-اطلاعات-دستگاه" aria-label="Permalink to &quot;1. اطلاعات دستگاه&quot;">​</a></h2><p>ابتدا اطلاعات پایه دستگاه را ثبت کنید.</p><ul><li>[ ] مدل گوشی و شماره مدل بررسی شد.</li><li>[ ] نسخه Android مشخص شد.</li><li>[ ] نسخه One UI مشخص شد.</li><li>[ ] آخرین به‌روزرسانی سیستم‌عامل بررسی شد.</li><li>[ ] تاریخ و نسخه کلاینت VPN ثبت شد.</li></ul><p>مسیر مشاهده نسخه سیستم‌عامل:</p><p><code>Settings → About phone → Software information</code></p><h2 id="_2-تنظیمات-شبکه-موبایل" tabindex="-1">2. تنظیمات شبکه موبایل <a class="header-anchor" href="#_2-تنظیمات-شبکه-موبایل" aria-label="Permalink to &quot;2. تنظیمات شبکه موبایل&quot;">​</a></h2><h3 id="mobile-data" tabindex="-1">Mobile Data <a class="header-anchor" href="#mobile-data" aria-label="Permalink to &quot;Mobile Data&quot;">​</a></h3><ul><li>[ ] دیتای موبایل بدون VPN به‌درستی کار می‌کند.</li><li>[ ] سیم‌کارت موردنظر برای Mobile Data انتخاب شده است.</li><li>[ ] Airplane Mode خاموش است.</li><li>[ ] Network Mode روی حالت خودکار مناسب اپراتور قرار دارد.</li><li>[ ] انتخاب اپراتور روی Automatic است.</li></ul><p>مسیرهای معمول:</p><p><code>Settings → Connections → SIM manager</code></p><p><code>Settings → Connections → Mobile networks</code></p><h3 id="apn" tabindex="-1">APN <a class="header-anchor" href="#apn" aria-label="Permalink to &quot;APN&quot;">​</a></h3><ul><li>[ ] APN فعال با اپراتور سیم‌کارت مطابقت دارد.</li><li>[ ] مقادیر APN با تنظیمات رسمی اپراتور مقایسه شده‌اند.</li><li>[ ] APN غیرضروری یا ناشناس وجود ندارد.</li></ul><p><strong>مهم:</strong> بدون ثبت تنظیمات فعلی، APN را تغییر ندهید. در صورت وجود مغایرت، ابتدا از تنظیمات رسمی اپراتور استفاده کنید.</p><p>مسیر:</p><p><code>Settings → Connections → Mobile networks → Access Point Names</code></p><p>در صورت نیاز به بازگردانی تنظیمات پیش‌فرض:</p><p><code>Access Point Names → More → Reset to default</code></p><h3 id="network-test" tabindex="-1">Network Test <a class="header-anchor" href="#network-test" aria-label="Permalink to &quot;Network Test&quot;">​</a></h3><ul><li>[ ] یک سایت HTTPS بدون VPN باز می‌شود.</li><li>[ ] اینترنت با Wi-Fi نیز آزمایش شده است.</li><li>[ ] اتصال با حداقل دو اپراتور مستقل آزمایش شده است.</li></ul><h2 id="_3-dns-و-تنظیمات-اتصال" tabindex="-1">3. DNS و تنظیمات اتصال <a class="header-anchor" href="#_3-dns-و-تنظیمات-اتصال" aria-label="Permalink to &quot;3. DNS و تنظیمات اتصال&quot;">​</a></h2><h3 id="private-dns" tabindex="-1">Private DNS <a class="header-anchor" href="#private-dns" aria-label="Permalink to &quot;Private DNS&quot;">​</a></h3><ul><li>[ ] وضعیت Private DNS بررسی شد.</li><li>[ ] هیچ Hostname ناشناس یا قدیمی تنظیم نشده است.</li><li>[ ] برای تست پایه، حالت Automatic انتخاب شده است.</li></ul><p>مسیر:</p><p><code>Settings → Connections → More connection settings → Private DNS</code></p><p>در بعضی نسخه‌ها می‌توانید عبارت Private DNS را در جست‌وجوی Settings وارد کنید.</p><h3 id="proxy" tabindex="-1">Proxy <a class="header-anchor" href="#proxy" aria-label="Permalink to &quot;Proxy&quot;">​</a></h3><ul><li>[ ] در تنظیمات Wi-Fi، Proxy روی None است؛ مگر اینکه عمداً از Proxy استفاده شود.</li><li>[ ] برنامه‌های DNS Changer و فایروال بررسی شده‌اند.</li><li>[ ] برنامه‌های AdBlock دارای قابلیت VPN بررسی شده‌اند.</li></ul><h2 id="_4-android-vpn-settings" tabindex="-1">4. Android VPN Settings <a class="header-anchor" href="#_4-android-vpn-settings" aria-label="Permalink to &quot;4. Android VPN Settings&quot;">​</a></h2><h3 id="vpn-profiles" tabindex="-1">VPN Profiles <a class="header-anchor" href="#vpn-profiles" aria-label="Permalink to &quot;VPN Profiles&quot;">​</a></h3><ul><li>[ ] پروفایل‌های VPN قدیمی و بلااستفاده بررسی شدند.</li><li>[ ] VPNهای فعال و برنامه‌های دارای مجوز VPN شناسایی شدند.</li><li>[ ] هم‌زمان فقط یک کلاینت VPN برای آزمایش استفاده می‌شود.</li></ul><p>مسیر:</p><p><code>Settings → Connections → More connection settings → VPN</code></p><h3 id="always-on-vpn" tabindex="-1">Always-on VPN <a class="header-anchor" href="#always-on-vpn" aria-label="Permalink to &quot;Always-on VPN&quot;">​</a></h3><ul><li>[ ] وضعیت Always-on VPN بررسی شد.</li><li>[ ] گزینه Block connections without VPN بررسی شد.</li><li>[ ] هیچ VPN قدیمی به‌صورت اجباری فعال نیست.</li></ul><div class="tip custom-block"><p class="custom-block-title">نکته</p><p>گزینه Block connections without VPN می‌تواند دسترسی اینترنت خارج از تونل را مسدود کند. اگر این گزینه فعال است، قبل از تغییر، اثر آن را بررسی و خاموش کنید.</p></div><h2 id="_5-samsung-battery-restrictions" tabindex="-1">5. Samsung Battery Restrictions <a class="header-anchor" href="#_5-samsung-battery-restrictions" aria-label="Permalink to &quot;5. Samsung Battery Restrictions&quot;">​</a></h2><p>محدودیت‌های باتری ممکن است اجرای پس‌زمینه و پایداری VPN را مختل کنند.</p><ul><li>[ ] Power Saving Mode برای تست خاموش است.</li><li>[ ] Data Saver بررسی شده است.</li><li>[ ] کلاینت VPN در Deep Sleeping Apps قرار ندارد.</li><li>[ ] کلاینت VPN در Sleeping Apps قرار ندارد.</li><li>[ ] محدودیت باتری برنامه بررسی شده است.</li></ul><p>مسیر معمول:</p><p><code>Settings → Battery → Background usage limits</code></p><p>در صورت وجود گزینه Never sleeping apps، می‌توانید کلاینت VPN را به آن اضافه کنید.</p><p>همچنین:</p><p><code>Settings → Apps → [VPN Client] → Battery</code></p><p>برای تست، اجازه اجرای پس‌زمینه را محدود نکنید یعنی روی گزینه‌ی <strong>optimized</strong> یا <strong>Unrestricted</strong> قرار دهید.</p><h2 id="_6-vpn-client-configuration" tabindex="-1">6. VPN Client Configuration <a class="header-anchor" href="#_6-vpn-client-configuration" aria-label="Permalink to &quot;6. VPN Client Configuration&quot;">​</a></h2><p>تنظیمات این بخش به کلاینت مورد استفاده وابسته است.</p><h3 id="v2rayng" tabindex="-1">V2RayNG <a class="header-anchor" href="#v2rayng" aria-label="Permalink to &quot;V2RayNG&quot;">​</a></h3><ul><li>[ ] نسخه برنامه ثبت شده است.</li><li>[ ] کانفیگ از منبع معتبر دریافت شده است.</li><li>[ ] کانفیگ در برنامه دیگری نیز آزمایش شده است.</li><li>[ ] Routing روی حالت موردنظر تنظیم شده است.</li><li>[ ] DNS داخلی برنامه بررسی شده است.</li><li>[ ] تنظیمات IPv6 بررسی شده‌اند.</li><li>[ ] تنظیمات Mux و Fragmentation بدون تغییرات آزمایشی متعدد بررسی شده‌اند.</li><li>[ ] Log برنامه برای یافتن خطا بررسی شده است.</li></ul><p><strong>توجه:</strong> در مرحله اول تمام تنظیمات کلاینت را روی حالت پیش‌فرض یا تنظیمات توصیه‌شده سازنده نگه دارید. تغییر هم‌زمان چند گزینه، تشخیص علت اصلی را دشوار می‌کند.</p><h3 id="سایر-کلاینت‌ها" tabindex="-1">سایر کلاینت‌ها <a class="header-anchor" href="#سایر-کلاینت‌ها" aria-label="Permalink to &quot;سایر کلاینت‌ها&quot;">​</a></h3><p>برای Hiddify، NekoBox، v2rayNG و سایر کلاینت‌ها، موارد زیر نیز بررسی شوند:</p><ul><li>نسخه برنامه</li><li>مجوز ایجاد VPN</li><li>DNS Configuration</li><li>Routing Mode</li><li>وضعیت اتصال تونل</li><li>گزارش خطا و زمان وقوع آن</li></ul><h2 id="_7-connectivity-tests" tabindex="-1">7. Connectivity Tests <a class="header-anchor" href="#_7-connectivity-tests" aria-label="Permalink to &quot;7. Connectivity Tests&quot;">​</a></h2><p>آزمایش‌ها را به همین ترتیب انجام دهید.</p><h3 id="test-a-—-baseline" tabindex="-1">Test A — Baseline <a class="header-anchor" href="#test-a-—-baseline" aria-label="Permalink to &quot;Test A — Baseline&quot;">​</a></h3><ul><li>[ ] Wi-Fi بدون VPN</li><li>[ ] Mobile Data بدون VPN</li><li>[ ] باز شدن چند سایت HTTPS</li><li>[ ] عملکرد DNS در اینترنت عادی</li></ul><h3 id="test-b-—-independent-vpn" tabindex="-1">Test B — Independent VPN <a class="header-anchor" href="#test-b-—-independent-vpn" aria-label="Permalink to &quot;Test B — Independent VPN&quot;">​</a></h3><ul><li>[ ] اتصال Windscribe با IKEv2</li><li>[ ] آزمایش حداقل دو سرور</li><li>[ ] آزمایش روی Wi-Fi</li><li>[ ] آزمایش روی Mobile Data</li></ul><h3 id="test-c-—-proxy-client" tabindex="-1">Test C — Proxy Client <a class="header-anchor" href="#test-c-—-proxy-client" aria-label="Permalink to &quot;Test C — Proxy Client&quot;">​</a></h3><ul><li>[ ] اتصال با کانفیگ سالم VLESS</li><li>[ ] آزمایش همان کانفیگ روی Wi-Fi</li><li>[ ] آزمایش همان کانفیگ روی سیم‌کارت اول</li><li>[ ] آزمایش همان کانفیگ روی سیم‌کارت دوم</li><li>[ ] ثبت خطای دقیق کلاینت</li></ul><h3 id="test-d-—-comparison" tabindex="-1">Test D — Comparison <a class="header-anchor" href="#test-d-—-comparison" aria-label="Permalink to &quot;Test D — Comparison&quot;">​</a></h3><p>اگر امکان دارد، همان کانفیگ و همان کلاینت را روی یک گوشی دیگر با همان اپراتور آزمایش کنید.</p><p>این آزمایش کمک می‌کند مشکل دستگاه از مشکل شبکه یا کانفیگ تفکیک شود.</p><h2 id="_8-diagnostic-report" tabindex="-1">8. Diagnostic Report <a class="header-anchor" href="#_8-diagnostic-report" aria-label="Permalink to &quot;8. Diagnostic Report&quot;">​</a></h2><p>در پایان، اطلاعات زیر را برای تحلیل ارسال کنید.</p><h3 id="device" tabindex="-1">Device <a class="header-anchor" href="#device" aria-label="Permalink to &quot;Device&quot;">​</a></h3><ul><li>Model:</li><li>Android Version:</li><li>One UI Version:</li><li>VPN Client:</li><li>Client Version:</li></ul><h3 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li>Operator 1:</li><li>Operator 2:</li><li>Wi-Fi Test:</li><li>Mobile Data Test:</li></ul><h3 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Test</th><th>Result</th></tr></thead><tbody><tr><td>Internet without VPN</td><td></td></tr><tr><td>Windscribe IKEv2</td><td></td></tr><tr><td>VLESS on Wi-Fi</td><td></td></tr><tr><td>VLESS on SIM 1</td><td></td></tr><tr><td>VLESS on SIM 2</td><td></td></tr><tr><td>DNS</td><td></td></tr></tbody></table><h3 id="error-details" tabindex="-1">Error Details <a class="header-anchor" href="#error-details" aria-label="Permalink to &quot;Error Details&quot;">​</a></h3><ul><li>Exact error:</li><li>Does connection establish?</li><li>Does traffic pass through?</li><li>Does the problem occur on all servers?</li><li>Does the problem occur on all operators?</li></ul><br><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Important Notes</p><ul><li>قبل از ثبت وضعیت اولیه، تنظیمات شبکه را Reset نکنید.</li><li>APN را بدون بررسی اطلاعات رسمی اپراتور تغییر ندهید.</li><li>نصب چند VPN هم‌زمان به معنی امکان استفاده هم‌زمان از همه آن‌ها نیست.</li><li>موفقیت اتصال IKEv2 لزوماً سلامت تمام پروتکل‌های VPN را اثبات نمی‌کند.</li><li>اطلاعات حساس مانند UUID، Password، Private Key و Subscription URL را در گزارش ارسال نکنید.</li><li>اگر اتصال اینترنت پایه نیز مشکل دارد، ابتدا همان مشکل را بررسی کنید.</li></ul></div><h3 id="official-references" tabindex="-1">Official References <a class="header-anchor" href="#official-references" aria-label="Permalink to &quot;Official References&quot;">​</a></h3><ul><li><a href="https://www.samsung.com/us/support/troubleshoot/TSG10004575" target="_blank" rel="noreferrer">Samsung Network Troubleshooting</a></li><li><a href="https://www.samsung.com/us/support/answer/ANS10002546" target="_blank" rel="noreferrer">Samsung Connection Settings</a></li><li><a href="https://developer.samsung.com/mobile/app-management.html" target="_blank" rel="noreferrer">Samsung Background App Management</a></li></ul>',82)])])}const b=i(o,[["render",r]]);export{u as __pageData,b as default};
